cd /run/stage/world && node -e '
const fs=require("fs");
const plan=JSON.parse(fs.readFileSync("shift-plan.json"));
const night=JSON.parse(fs.readFileSync("night.json"));
const limits=[80,40,50,70];
const eta90=0.9, eta85=0.85;
const dep=[]; const mar=[];
for (const b of night.buses){let ac=0; for(let i=b.fromSlot;i<b.untilSlot;i++) ac+=plan.acKw[i]*night.slotHours; const end=b.startKwh+ac*eta90; dep.push(end); mar.push(end-b.requiredKwh);}
const dep85=[]; const mar85=[];
for (const b of night.buses){let ac=0; for(let i=b.fromSlot;i<b.untilSlot;i++) ac+=plan.acKw[i]*night.slotHours; const end=b.startKwh+ac*eta85; dep85.push(end); mar85.push(end-b.requiredKwh);}
console.log({acKw:plan.acKw, withinLimits:plan.acKw.every((p,i)=>p<=limits[i]), dep, mar, dep85, mar85});
console.log(fs.readFileSync("release.json","utf8"));
' && node --test 2>&1 | tail -12
